        vm.warp(block.timestamp + 7 days);

        vm.prank(bob);
        veToken.updateReward();

        vm.prank(alice);
        veToken.updateReward();

        console.log(veToken.earned(bob, address(usdt))); // 99e6
        console.log(veToken.earned(alice, address(usdt))); // 99e6
    }
```

