    require(block.timestamp >= saleConfig.settleTime, "Settlement: too early");
    require(!settlementFinalized, "Settlement: finalized");

    _finalizeSettlement();
    uint256 curBalance = purchaseToken.balanceOf(address(this));
    uint256 safetyBuffer = 1000;
