	deal(address(_gauge.token0()), user1, 1 ether);
	vm.startPrank(address(user1));
	_gauge.token0().approve(address(_rebaseReward), 1 ether);
	_rebaseReward.incentivize(address(_gauge.token0()), 1 ether);
