function rate(address _vault, address _asset) external returns (uint256 latestAnswer) {
    VaultAdapterStorage storage $ = getVaultAdapterStorage();
    uint256 elapsed;
    uint256 utilization;
    if (block.timestamp > $.utilizationData[_asset].lastUpdate) {
