    recipients[_receiver].push(_count);
    customers[msg.sender].push(_count);

    usdt.safeTransferFrom(msg.sender, address(this), _amount);

    emit CreateTransactionEvent(
        msg.sender,
        _receiver,
        _amount,
        _count,
        block.timestamp + blocktime,
        _challengeId
    );
}
