        crvusd.approve(address(lendingPool), type(uint256).max);
        lendingPool.deposit(INITIAL_BALANCE);
        rToken.approve(address(stabilityPool), type(uint256).max);
        vm.stopPrank();

        vm.startPrank(user2);
        crvusd.approve(address(lendingPool), type(uint256).max);
        lendingPool.deposit(INITIAL_BALANCE);
        rToken.approve(address(stabilityPool), type(uint256).max);
        vm.stopPrank();

        vm.startPrank(user3);
        crvusd.approve(address(lendingPool), type(uint256).max);
        lendingPool.deposit(INITIAL_BALANCE);
        rToken.approve(address(stabilityPool), type(uint256).max);
        vm.stopPrank();
    }
