            orgNftRecipient: u.carl,
            orgName: "Carl's Second Org",
            orgIpMetadata: ipMetadataDefault,
            signature: signature2,
            storyNftInitParams: storyNftInitParams // Carl will be the signer for this org too
        });
        vm.stopPrank();

