        amountIn: wethIn,
        amountOutMinimum: 0,
        sqrtPriceLimitX96: 0
    });
    v3Router.exactInputSingle(swapParams);

    // Deposit on ULTI reverts due to price slippage
    vm.expectRevert("Price slippage check");
    ulti.depositNative{value: 0.00001 ether}(address(0), 0, block.timestamp, false);
