        if (collateral.precision > 0) {
            revert IGeneralErrors.DoesntExist();
        }

        bool toggled = !collateral.isActive;
        collateral.isActive = toggled;

        emit ITradingStorageUtils.CollateralUpdated(_collateralIndex, toggled);
    }
