+ (,, uint256 periodFinish) = _getRewardPoolMetrics(address(rewarder));
+ if (periodFinish > block.timestamp) {
+  periodFinish = block.timestamp 
+ }
+ uint256 timeBetweenSnapshots = periodFinish - lastSnapshotTimestamp;
