        // Utilization rate is 0 when there are no borrows
        if (borrows == 0) {
            return 0;
        }

        // return (borrows * 1e18) / (cash + borrows - reserves);
-       return borrows.divWadDown((cash - reserves));
+       return borrows.divWadDown((cash + borrows - reserves));
    }
```

