            console2.log("[>] Vault's margin: %s", vaultStatus.position.margin );
            console2.log("[>] Vault's quote position: %s", vaultStatus.position.amountQuote );
            console2.log("[>] Vault's base position: %s", vaultStatus.position.amountBase );

