        controller.earningWithdraw(true, 0, payable(bob), 0);
        // Bob gets unwrapped wstETH
        assertGe(bob.balance, 3 ether + 1 wei);
        // Bob has the other wstETH
        assertEq(WSTETH.balanceOf(bob), 10 ether - 3 ether - 1 wei);
    }
}
```

## Recommendation
