function setRefereeFeeAmount(
  address _referee,
  address _adapterAddress,
  uint256 _feeAmount
) public override onlyFactory {
  refereeFeeAmounts[_referee][_adapterAddress] = _feeAmount;
  emit SetRefereeFeeAmount(_referee, _adapterAddress, _feeAmount);
