                erc721s[i].setApprovalForAll(address(conduit), true);
            }

            // set all approvals for erc1155 tokens
            for (uint256 i = 0; i < erc1155s.length; ++i) {
                erc1155s[i].setApprovalForAll(address(conduit), true);
            }

            // stop impersonating
            vm.stopPrank();
        }
