                    rentalOrder.lender,
                    rentalOrder.renter,
                    rentalOrder.rentalWallet,
                    rentalOrder.startTimestamp,
                    rentalOrder.endTimestamp
                );
            }

            // the owner of the rental wallet fulfills the advanced order, and marks the rental wallet
