    emit LOCConverted(
        _locId,
        _initiatorAddress,
        _liquidatorAddress,
        liquidationContext.liquidationAmount,
        liquidationContext.liquidatorFeeAmount,
        liquidationContext.creditedTokenAmountToReceive
