        vm.prank(alice);
        stp.mintFor{value: 1e18}(alice, 1e18);
        stp.setSub(alice, 100);

        vm.prank(bob);
        stp.mintFor{value: 1e18}(bob, 1e18);
        stp.setSub(bob, 200);

        vm.prank(charlie);
        stp.mintFor{value: 1e18}(charlie, 1e18);
        stp.setSub(charlie, 300);

        stp.setRewards(100000, 100000, 600);

        vm.prank(charlie);
        stp.withdrawRewards();

        stp.slash(charlie, 300);

        vm.prank(bob);
        stp.withdrawRewards();
    }
```

