-           // Update the last vouchers coresponsing Vouchee item
-           uint128 voucheeIdx = voucherIndexes[borrower][lastVoucher.staker].idx;
-           vouchees[staker][voucheeIdx].voucherIndex = removeVoucherIndex.idx.toUint96();
+           // Update the last vouchers coresponsing Vouchee item
