Manual Review

## Recommendation

Send collateral/debt then delete:

    -   if (repaid == loan.amount) delete loans[loanID];
    +   if (repaid == loan.amount) {
    +       debt.transferFrom(msg.sender, loan.lender, loan.amount);
    +       collateral.transfer(owner, loan.collateral);
    +       delete loans[loanID];
    +       return;
    +   }

