            _feesPositions[id][msg.sender].burn(long0Fees, long1Fees, shortFees);

            if (long0Fees != 0 || long1Fees != 0 || shortFees != 0) _removeTokenEnumeration(msg.sender, address(0), id, 0);

            // stop the reentrancy guard
            lowerGuard(key);
