            if (_trade.direction) {
                if (_trade.tpPrice > _price) revert("6"); //LimitNotMet
            } else {
                if (_trade.tpPrice < _price) revert("6"); //LimitNotMet
            }
    -       _limitPrice = _trade.tpPrice;
    +       _limitPrice = _price;
