function positionInWantToken()
    public
    view
    override
    returns (uint256, uint256)
{
    (
        uint256 stakedLpBalanceInETH,
        uint256 lpBalanceInETH,
        uint256 ethBalance
    ) = \_getTotalBalancesInETH(true);

