 if (\_flashnum == 0) {
 \_initiateGeistFlashLoan(info);
 } else if (\_flashnum == 2) {
 \_initiateCreamFlashLoan(info);
 } else {
 revert(Errors.VL\_INVALID\_FLASH\_NUMBER);
 }
}

```
**code/contracts/fantom/flashloans/FlasherFTM.sol:L46-L55**



```
modifier isAuthorized() {
 require(
