    // Instantiate the pair
    IUniswapV2Pair the_pair = IUniswapV2Pair(pair_address);
    // Get the reserves
    uint256[] memory reserve_pack = new uint256[](3);  // [0] = FRAX, [1] = FXS, [2] = Collateral
